create table if not exists public.media_folders (id bigint generated by default as identity primary key, name varchar(80) not null, created_at timestamptz not null default now());
create table if not exists public.media (id bigint generated by default as identity primary key, folder_id bigint, storage_key varchar(120) not null unique, filename varchar(255) not null, mime varchar(120) not null default 'application/octet-stream', size bigint not null default 0, width integer, height integer, usage_type varchar(40) not null default 'general', hash varchar(64), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.media_variants (id bigint generated by default as identity primary key, media_id bigint not null references public.media(id) on delete cascade, variant varchar(40) not null, storage_key varchar(120) not null, width integer, height integer, size bigint not null default 0, format varchar(10) not null default 'webp', created_at timestamptz not null default now(), unique(media_id, variant));
create table if not exists public.media_translations (id bigint generated by default as identity primary key, media_id bigint not null references public.media(id) on delete cascade, locale_id bigint not null references public.locales(id) on delete cascade, alt varchar(255) not null default '', caption varchar(500) not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(media_id, locale_id));
create index if not exists media_filename_idx on public.media(filename);
create index if not exists media_usage_idx on public.media(usage_type);
create index if not exists media_variants_media_idx on public.media_variants(media_id);
create index if not exists media_translations_locale_idx on public.media_translations(locale_id);
alter table public.media_folders enable row level security;
alter table public.media enable row level security;
alter table public.media_variants enable row level security;
alter table public.media_translations enable row level security;
revoke all on table public.media_folders, public.media, public.media_variants, public.media_translations from anon, authenticated;
